component.css:
.cor{position:relative;width:100%;aspect-ratio:1672/941;container-type:size;overflow:hidden;background:#04040a;font-family:serif;user-select:none}
.cam{position:absolute;inset:0;perspective:40cqh;perspective-origin:50% 52%}
.world{position:absolute;left:50%;top:50%;width:0;height:0;transform-style:preserve-3d}
.w{position:absolute;left:0;top:0;transform-origin:0 0;backface-visibility:hidden}
.wl{width:840cqh;height:60cqh;transform:translate3d(-45cqh,-30cqh,420cqh) rotateY(90deg);background:linear-gradient(180deg,rgba(4,4,10,.94) 0%,rgba(22,17,30,0) 24%,rgba(26,20,36,0) 60%,rgba(4,4,10,.96) 100%),repeating-linear-gradient(90deg,#241d2f 0 3cqh,#1a1425 3cqh 30cqh);box-shadow:inset 0 0 26cqh #000}
.wr{width:840cqh;height:60cqh;transform:translate3d(45cqh,-30cqh,-420cqh) rotateY(-90deg);background:linear-gradient(180deg,rgba(4,4,10,.94) 0%,rgba(22,17,30,0) 24%,rgba(26,20,36,0) 60%,rgba(4,4,10,.96) 100%),repeating-linear-gradient(90deg,#241d2f 0 3cqh,#1a1425 3cqh 30cqh);box-shadow:inset 0 0 26cqh #000}
.wl::after,.wr::after{content:"";position:absolute;left:0;top:13%;width:100%;height:.9cqh;background:repeating-linear-gradient(90deg,rgba(150,205,255,.45) 0 1.4cqh,rgba(150,205,255,0) 1.4cqh 30cqh);filter:blur(.2cqh)}
.wf{width:90cqh;height:840cqh;transform:translate3d(-45cqh,30cqh,-420cqh) rotateX(90deg);background:repeating-linear-gradient(180deg,#151020 0 3cqh,#0d0a14 3cqh 30cqh);box-shadow:inset 0 0 30cqh #000}
.wf::after{content:"";position:absolute;left:49.65%;top:0;width:.7cqh;height:100%;background:rgba(140,175,215,.15)}
.wc{width:90cqh;height:840cqh;transform:translate3d(-45cqh,-30cqh,420cqh) rotateX(-90deg);background:#0a0810;box-shadow:inset 0 0 30cqh #000}
.wc::after{content:"";position:absolute;left:0;top:49.65%;width:100%;height:.7cqh;background:rgba(150,205,255,.2);filter:blur(.3cqh)}
.door{position:absolute;left:0;top:0;width:44cqh;height:52cqh;transform:translate3d(-22cqh,-22cqh,-400cqh);background:linear-gradient(180deg,#0f1724,#1d2c40);border:.5cqh solid #3d5a7a;box-shadow:0 0 10cqh 1.5cqh rgba(110,170,220,.22);transition:box-shadow .6s,border-color .6s;opacity:.92}
.door::after{content:"";position:absolute;left:38%;right:38%;top:14%;bottom:10%;background:#070b12}
.door.is-real{border-color:#7ce8c8;box-shadow:0 0 16cqh 4cqh rgba(120,240,205,.45)}
.door.is-open{border-color:#fff;box-shadow:0 0 26cqh 8cqh rgba(255,255,255,.75);opacity:1}
.vig{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 52%,transparent 38%,rgba(0,0,0,.82) 100%)}
.flash{position:absolute;inset:0;background:#e7eeff;opacity:1;pointer-events:none;transition:opacity 1.4s}
.whisper{position:absolute;left:0;right:0;top:11%;text-align:center;color:#93a9c6;font-size:3.6cqh;letter-spacing:.4em;text-shadow:0 0 2.4cqh rgba(70,160,255,.4);opacity:0;transition:opacity .9s;pointer-events:none}
.whisper.is-on{opacity:.88}
.hint{position:absolute;left:0;right:0;bottom:4.5%;text-align:center;color:#5c6d84;font-size:2.1cqh;letter-spacing:.3em;opacity:.85;transition:opacity 1.2s;pointer-events:none}
.hint.is-off{opacity:0}
.pads{position:absolute;right:3%;bottom:5%;display:flex;flex-direction:column;gap:1.6cqh}
.pad{width:14cqh;height:14cqh;background:rgba(18,26,42,.55);border:1px solid rgba(140,170,210,.28);border-radius:2cqh;color:#9fb6d4;font-size:5cqh;cursor:pointer;touch-action:none}
.pad:active{background:rgba(70,110,160,.55)}
.cor.is-shake .cam{animation:cshk .28s linear}
@keyframes cshk{20%{transform:translate(1.5cqh,-.7cqh)}45%{transform:translate(-1.2cqh,.5cqh)}70%{transform:translate(.8cqh,1cqh)}}

component.script:
"use strict";(() => {
var D = String.fromCharCode(36);
var SL = String.fromCharCode(47);
var root = document.getElementById("corRoot");
if (!root) return;
var q = s => root.querySelector(s);
var world = q("#corWorld"), flash = q("#corFlash"), wh = q("#corWhisper"), door = q("#corDoor"), hint = q("#corHint");
var NEXT = "大都会真结局追逐战";
var p = 0, loops = 0, backs = 0, free = false, gone = false;
var fwd = false, bwd = false, SPD = 9, last = 0;
var FWDW = ["出口没有变近。", "向前，只是回到起点。", "……倒退。", "……倒退。"];
var whT = 0;
var whisper = t => {
  wh.textContent = t;
  wh.classList.add("is-on");
  clearTimeout(whT);
  whT = setTimeout(() => wh.classList.remove("is-on"), 4200);
};
var AC = null, master = null, echo = null, nz = null;
var audio = () => {
  if (AC) { try { AC.resume(); } catch (e) {} return; }
  try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return; }
  master = AC.createGain(); master.gain.value = 0.9; master.connect(AC.destination);
  var lp = AC.createBiquadFilter(); lp.type = "lowpass"; lp.frequency.value = 300; lp.connect(master);
  var mk = (f, g, ty) => { var o = AC.createOscillator(); o.type = ty; o.frequency.value = f; var gg = AC.createGain(); gg.gain.value = g; o.connect(gg); gg.connect(lp); o.start(); };
  mk(55, 0.05, "sine"); mk(55.6, 0.045, "sine"); mk(110.4, 0.013, "triangle"); mk(27.5, 0.05, "sine");
  var lfo = AC.createOscillator(); lfo.frequency.value = 0.05; var lg = AC.createGain(); lg.gain.value = 80; lfo.connect(lg); lg.connect(lp.frequency); lfo.start();
  echo = AC.createDelay(2); echo.delayTime.value = 0.42; var fb = AC.createGain(); fb.gain.value = 0.42; echo.connect(fb); fb.connect(echo); var eg = AC.createGain(); eg.gain.value = 0.5; echo.connect(eg); eg.connect(master);
  setInterval(() => { if (Math.random() < 0.55) creak(); }, 8500);
};
var creak = () => {
  if (!AC) return;
  var o = AC.createOscillator(); o.type = "sawtooth";
  var f = 300 + Math.random() * 520;
  o.frequency.setValueAtTime(f, AC.currentTime);
  o.frequency.exponentialRampToValueAtTime(f * 0.38, AC.currentTime + 1.4);
  var g = AC.createGain();
  g.gain.setValueAtTime(0.0001, AC.currentTime);
  g.gain.exponentialRampToValueAtTime(0.018, AC.currentTime + 0.09);
  g.gain.exponentialRampToValueAtTime(0.0001, AC.currentTime + 1.5);
  o.connect(g); g.connect(echo);
  o.start(); o.stop(AC.currentTime + 1.6);
};
var sfx = () => {
  if (!AC) return;
  if (!nz) { nz = AC.createBuffer(1, 5556, AC.sampleRate); var ch = nz.getChannelData(0); var i = 0; while (i < ch.length) { ch[i] = (Math.random() * 2 - 1) * 0.7; i++; } }
  var s = AC.createBufferSource(); s.buffer = nz;
  var g = AC.createGain();
  g.gain.setValueAtTime(0.17, AC.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001, AC.currentTime + 0.3);
  var bp = AC.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = 750; bp.Q.value = 0.6;
  s.connect(bp); bp.connect(g); g.connect(master);
  s.start(); s.stop(AC.currentTime + 0.32);
};
var glitch = dir => {
  sfx();
  root.classList.remove("is-shake"); void root.offsetWidth; root.classList.add("is-shake");
  flash.style.transition = "opacity .1s"; flash.style.opacity = "1";
  setTimeout(() => { flash.style.opacity = "0"; }, 120);
  p = 0;
  if (dir === 1) { loops++; whisper(FWDW[Math.min(loops - 1, 3)]); }
  else { backs++; if (backs >= 2) { free = true; door.classList.add("is-real"); whisper("门，接受了。"); } else whisper("再一次。"); }
};
var goNext = () => {
  if (gone) return;
  gone = true;
  flash.style.transition = "opacity 1s"; flash.style.opacity = "1";
  setTimeout(() => {
    try { if (typeof changeMsg === "function") changeMsg("<" + D + NEXT + D + ">" + "<" + SL + D + NEXT + D + ">"); } catch (e) {}
  }, 950);
};
var frame = now => {
  if (gone) return;
  var dt = Math.min(0.05, (now - last) * 0.001); last = now;
  var v = (fwd ? 1 : 0) - (bwd ? 1 : 0);
  if (v) { p += v * SPD * dt; audio(); }
  var bob = v ? Math.sin(now * 0.011) * 0.55 : 0;
  world.style.transform = "translate3d(0," + bob.toFixed(2) + "cqh," + (p * 10).toFixed(1) + "cqh)";
  if (!free && p >= 33) glitch(1);
  if (p <= -33) glitch(2);
  if (free && p >= 34.5) door.classList.add("is-open");
  if (free && p >= 39.2) { goNext(); return; }
  requestAnimationFrame(frame);
};
document.addEventListener("keydown", e => {
  if (e.code === "KeyW" || e.code === "ArrowUp") { e.preventDefault(); fwd = true; audio(); }
  else if (e.code === "KeyS" || e.code === "ArrowDown") { e.preventDefault(); bwd = true; audio(); }
});
document.addEventListener("keyup", e => {
  if (e.code === "KeyW" || e.code === "ArrowUp") fwd = false;
  else if (e.code === "KeyS" || e.code === "ArrowDown") bwd = false;
});
root.querySelectorAll(".pad").forEach(el => {
  var set = on => {
    if (el.dataset.mv === "f") fwd = on; else bwd = on;
    if (on) audio();
  };
  el.addEventListener("pointerdown", e => { e.preventDefault(); el.setPointerCapture(e.pointerId); set(true); });
  el.addEventListener("pointerup", () => set(false));
  el.addEventListener("pointercancel", () => set(false));
});
setTimeout(() => flash.style.opacity = "0", 350);
setTimeout(() => hint.classList.add("is-off"), 7000);
whisper("……这里是哪？");
last = performance.now();
requestAnimationFrame(frame);
})();
